// WhereP appends storage-level predicates to the TypeDefMutation builder. Using this method,
// users can use type-assertion to append predicates that do not depend on any generated package.
func (m *TypeDefMutation) WhereP(ps ...func(*sql.Selector)) {
	p := make([]predicate.TypeDef, len(ps))
	for i := range ps {
		p[i] = ps[i]
	}
	m.Where(p...)
}

// Op returns the operation name.
func (m *TypeDefMutation) Op() Op {
	return m.op
}

// SetOp allows setting the mutation operation.
func (m *TypeDefMutation) SetOp(op Op) {
	m.op = op
}

// Type returns the node type of this mutation (TypeDef).
func (m *TypeDefMutation) Type() string {
	return m.typ
}

// Fields returns all fields that were changed during this mutation. Note that in
// order to get all numeric fields that were incremented/decremented, call
// AddedFields().
func (m *TypeDefMutation) Fields() []string {
	fields := make([]string, 0, 2)
	if m.type_rn != nil {
		fields = append(fields, typedef.FieldTypeRn)
	}
	if m.exp_ck != nil {
		fields = append(fields, typedef.FieldExpCk)
	}
	return fields
}

// Field returns the value of a field with the given name. The second boolean
// return value indicates that this field was not set, or was not defined in the
// schema.
func (m *TypeDefMutation) Field(name string) (ent.Value, bool) {
	switch name {
	case typedef.FieldTypeRn:
		return m.TypeRn()
	case typedef.FieldExpCk:
		return m.ExpCk()
	}
	return nil, false
}

// OldField returns the old value of the field from the database. An error is
// returned if the mutation operation is not UpdateOne, or the query to the
// database failed.
func (m *TypeDefMutation) OldField(ctx context.Context, name string) (ent.Value, error) {
	switch name {
	case typedef.FieldTypeRn:
		return m.OldTypeRn(ctx)
	case typedef.FieldExpCk:
		return m.OldExpCk(ctx)
	}
	return nil, fmt.Errorf("unknown TypeDef field %s", name)
}

// SetField sets the value of a field with the given name. It returns an error if
// the field is not defined in the schema, or if the type mismatched the field
// type.
func (m *TypeDefMutation) SetField(name string, value ent.Value) error {
	switch name {
	case typedef.FieldTypeRn:
		v, ok := value.(int64)
		if !ok {
			return fmt.Errorf("unexpected type %T for field %s", value, name)
		}
		m.SetTypeRn(v)
		return nil
	case typedef.FieldExpCk:
		v, ok := value.(int64)
		if !ok {
			return fmt.Errorf("unexpected type %T for field %s", value, name)
		}
		m.SetExpCk(v)
		return nil
	}
	return fmt.Errorf("unknown TypeDef field %s", name)
}

// AddedFields returns all numeric fields that were incremented/decremented during
// this mutation.
func (m *TypeDefMutation) AddedFields() []string {
	var fields []string
	if m.addtype_rn != nil {
		fields = append(fields, typedef.FieldTypeRn)
	}
	if m.addexp_ck != nil {
		fields = append(fields, typedef.FieldExpCk)
	}
	return fields
}

// AddedField returns the numeric value that was incremented/decremented on a field
// with the given name. The second boolean return value indicates that this field
// was not set, or was not defined in the schema.
func (m *TypeDefMutation) AddedField(name string) (ent.Value, bool) {
	switch name {
	case typedef.FieldTypeRn:
		return m.AddedTypeRn()
	case typedef.FieldExpCk:
		return m.AddedExpCk()
	}
	return nil, false
}

// AddField adds the value to the field with the given name. It returns an error if
// the field is not defined in the schema, or if the type mismatched the field
// type.
func (m *TypeDefMutation) AddField(name string, value ent.Value) error {
	switch name {
	case typedef.FieldTypeRn:
		v, ok := value.(int64)
		if !ok {
			return fmt.Errorf("unexpected type %T for field %s", value, name)
		}
		m.AddTypeRn(v)
		return nil
	case typedef.FieldExpCk:
		v, ok := value.(int64)
		if !ok {
			return fmt.Errorf("unexpected type %T for field %s", value, name)
		}
		m.AddExpCk(v)
		return nil
	}
	return fmt.Errorf("unknown TypeDef numeric field %s", name)
}

// ClearedFields returns all nullable fields that were cleared during this
// mutation.
func (m *TypeDefMutation) ClearedFields() []string {
	return nil
}

// FieldCleared returns a boolean indicating if a field with the given name was
// cleared in this mutation.
func (m *TypeDefMutation) FieldCleared(name string) bool {
	_, ok := m.clearedFields[name]
	return ok
}

// ClearField clears the value of the field with the given name. It returns an
// error if the field is not defined in the schema.
func (m *TypeDefMutation) ClearField(name string) error {
	return fmt.Errorf("unknown TypeDef nullable field %s", name)
}

// ResetField resets all changes in the mutation for the field with the given name.
// It returns an error if the field is not defined in the schema.
func (m *TypeDefMutation) ResetField(name string) error {
	switch name {
	case typedef.FieldTypeRn:
		m.ResetTypeRn()
		return nil
	case typedef.FieldExpCk:
		m.ResetExpCk()
		return nil
	}
	return fmt.Errorf("unknown TypeDef field %s", name)
}

// AddedEdges returns all edge names that were set/added in this mutation.
func (m *TypeDefMutation) AddedEdges() []string {
	edges := make([]string, 0, 0)
	return edges
}

// AddedIDs returns all IDs (to other nodes) that were added for the given edge
// name in this mutation.
func (m *TypeDefMutation) AddedIDs(name string) []ent.Value {
	return nil
}

// RemovedEdges returns all edge names that were removed in this mutation.
func (m *TypeDefMutation) RemovedEdges() []string {
	edges := make([]string, 0, 0)
	return edges
}

// RemovedIDs returns all IDs (to other nodes) that were removed for the edge with
// the given name in this mutation.
func (m *TypeDefMutation) RemovedIDs(name string) []ent.Value {
	return nil
}

// ClearedEdges returns all edge names that were cleared in this mutation.
func (m *TypeDefMutation) ClearedEdges() []string {
	edges := make([]string, 0, 0)
	return edges
}

// EdgeCleared returns a boolean which indicates if the edge with the given name
// was cleared in this mutation.
func (m *TypeDefMutation) EdgeCleared(name string) bool {
	return false
}

// ClearEdge clears the value of the edge with the given name. It returns an error
// if that edge is not defined in the schema.
func (m *TypeDefMutation) ClearEdge(name string) error {
	return fmt.Errorf("unknown TypeDef unique edge %s", name)
}

// ResetEdge resets all changes to the edge with the given name in this mutation.
